 "pd3-r1": {
  "title": "Artificial intelligence in the workplace",
  "text": "In just a few years, artificial intelligence has moved from the research laboratories out into Danish workplaces. According to a new report from Dansk Erhverv, almost half of Danish companies now use some form of artificial intelligence, typically to write texts, answer customer enquiries or analyse data.\n\nMany employees find that the technology removes boring routine tasks. \"Before, I spent a whole day a month making reports. Now it takes an hour, and I can use the time to talk to the customers,\" says Line Mortensen, who works in finance at a medium-sized company in Vejle.\n\nNevertheless, there is also concern. The trade unions point out that administrative positions in particular may become redundant, and they are calling for companies to invest in further training so that employees can keep up with developments. \"It is not the technology itself that is the problem. The problem arises if people are not given the opportunity to learn new skills,\" says a spokesperson for HK.\n\nResearchers from Aarhus University also stress that artificial intelligence makes mistakes. The systems can invent information that sounds credible but is wrong. They therefore recommend that a human always checks the result before it is passed on to customers or authorities.\n\nThe report concludes that the companies that get the most out of the technology are those that involve their employees from the start and have clear guidelines for what it may be used for.",
  "questions": [
   {
    "q": "According to the report, what do companies typically use artificial intelligence for?",
    "options": [
     "To hire new employees",
     "To write texts, answer customers and analyse data",
     "To control machines in factories"
    ]
   },
   {
    "q": "What has Line Mortensen got more time for?",
    "options": [
     "Making reports",
     "Talking to the customers",
     "Going on further training"
    ]
   },
   {
    "q": "What are the trade unions calling for?",
    "options": [
     "A ban on artificial intelligence",
     "Higher pay for administrative employees",
     "That companies invest in further training"
    ]
   },
   {
    "q": "The researchers think that artificial intelligence always gives correct information."
   },
   {
    "q": "According to the report, the most successful companies have clear rules for the use of the technology."
   },
   {
    "q": "Line Mortensen's company has fired employees because of artificial intelligence."
   }
  ]
 },
