      "body": "Farm shop selling our own products: eggs, fruit and vegetables and apple juice. In addition, a large and varied range of groceries and beef, veal, lamb, venison, lamb, goat, chicken, duck and goose, as well as cheeses and vegetarian products. We are open every day 10-16. Also have a webshop."
