      "body": "Farm shop selling our own products, including animal-welfare delicacies, which are meat from small black-and-white pigs. Also a wide selection of groceries, fruit and vegetables from local and regional businesses. We are happy to try to get hold of whatever is asked for.\nAlso a wide selection of arts and crafts and gift items, produced by local people, much of it made from recycled materials. Opening hours: Thursday and Friday 14-18, Saturday 10-14. We are also open on selected Sundays and in connection with current events. Keep up to date on our website."
