   {
    "heading": "Lovely bathing beaches on Funen",
    "cards": [
     {
      "title": "Føns Strand",
      "sub": "south of Middelfart",
      "body": "Lovely, inviting sandy beach with very few stones. Clear, clean water, very child-friendly. Room for slightly bigger movements and ball games behind the beach. The beach has a Blue Flag. Toilet and kiosk by the beach."
     },
     {
      "title": "Elsehoved Strand",
      "sub": "between Nyborg and Svendborg",
      "body": "On East Funen lies the popular Elsehoved Strand. Drive out towards the water from the road between Nyborg and Svendborg. Elsehoved Strand is an excellent beach with fine sand and child-friendly depths, as well as lots of life in the summer months."
     },
     {
      "title": "Christiansminde Strand",
      "sub": "near Svendborg",
      "body": "This fine beach is within walking and cycling distance just east of Svendborg. You could use the lovely path along the water past the rowing club. The beach is popular and attracts both families with children and young people from morning to evening. The view is wonderful and invites picnics and barbecues. The water is lovely, and there is a bathing jetty where the famous veteran ship \"Helge\" moors. The beach invites ball games, there is a mini golf course and a playground, and the kiosk is famous for very large soft-serve ice creams."
     },
     {
      "title": "Fyns Badestrand",
      "sub": "near Nyborg",
      "body": "It is a large, lovely beach that was created when the West Bridge over the Great Belt was built. Here there is lots of lovely fine sand on the beach and a nice sandy bottom a little way out in the water. You don't have to go very far out before it is deep enough for a good swim. The strong current of water through the Great Belt makes sure that the bathing water is always clean and clear. If you don't wear swimwear, you lie on the outermost 150 metres of the beach – out towards the bridge. The beach has lifeguards, who sit in the towers from 10 to 18 in the summer period."
     },
     {
      "title": "Bøjden Strand",
      "sub": "near Faaborg",
      "body": "The beach is connected to Bøjden Strand Feriepark. It is a beautiful white sandy beach, where you have to go a really long way out before it gets deep. A popular and very child-friendly beach in southern Funen."
     },
     {
      "title": "Hasmark Strand",
      "sub": "near Otterup on North Funen",
      "body": "One of Funen's best and most popular bathing beaches. It stretches several kilometres from Enebærodde to Bårdesø and Tørresø Strand. Here the water is shallow and child-friendly. A long dike follows the beach and is an ideal opportunity for a walk. The campsite behind it is also very popular. But watch out for the current, because the water moves fast on North Funen, which gives good waves and fresh water, but also means you need to be careful when swimming."
     },
     {
      "title": "Bogense Marina og søbad",
      "sub": "in Bogense on North Funen",
      "body": "The town of Bogense is always worth a visit when summer is at its height and you need a swim. You can either choose the bathing beach to the left of the marina, or you can walk along the new harbour front and end up at the sea bath. Here there are floating jetties and rafts that you can have fun with. The sea bath is aimed at a slightly older audience, but later in the evening there are often many young people in and around the sea bath. On the beach by the marina there are good opportunities for families with children. Here the water is fairly shallow on the left side of the stone breakwaters."
     },
     {
      "title": "Ristinge Strand",
      "sub": "Langeland",
      "body": "On Langeland lies the famous Ristinge Strand, which is definitely one of the best bathing beaches on Funen. Famous, among other things, for its beautiful nature with 30-metre-high cliffs, and also a good place to look for fossils. Combine your swim with another nature experience, so that interesting stones can come home to the collection or simply be admired in the car on the way home."
     },
     {
      "title": "Smørmosen Strand",
      "sub": "Thurø south of Svendborg",
      "body": "There is something for all ages here: ring toss, bouncy pillow, play castle, climbing ropes, sandpit with digger, petanque, tetherball and not least an almost legendary mini golf course! In addition, there is a huge lawn and a lovely sandy beach. There are bushes you can lie in the shelter of, and you can park in the forest so that you don't come back to a boiling hot car after your trip to the beach.\nQuite simply Denmark's loveliest beach for children and the rest of the family."
     }
    ]
   }
