      "title": "B",
      "body": "■■■■■■\nFrom 1/1 2015 Dorthe Bruhn is entering into partnership with Kurt Olesen at the clinic at Sejers Allé 63, 8244 Nyby.\nThe clinic's telephone and consultation hours are unchanged."
