      "body": "Fun and effective training in our brand-new centre.\nWe are open 06.00-22.00, so you can train when it suits you.\nYou can also sign up for a class with one of our skilled instructors.\n■■■■■■\nSee you at Super Form!\nTel. 34 06 57 40 · www.super-form.dk"
