      "body": "■■■■■■\nFriday 7 June from 12-14 at Aktivitetshuset, Banevej 17.\nTheme: Public services online – an introduction to NemID, skat.dk, borger.dk and sundhed.dk.\nFeel free to bring your own computer. Participation is free.\nSign up on tel. 45 46 41 09"
