 "p15m-3": {
  "title": "Task 3 – Pensioners online",
  "instruction": "Read the text. Eight words are missing from the text (13-20). Choose the missing words. There are five words you will not need. See the example (0).",
  "text": "It is not only young people who spend a large part of their time on the internet. Many older people also say that it is very [[0]] for them to go online every day.\n\nGrethe Juhl is 72 years old and a pensioner. She has had a computer for several years, but she actually only uses it when she wants to go on the internet. For example, she often communicates with her daughter and her two grandchildren, who live in England. She [[13]] them a lot, because she only sees them once or twice a year. [[14]] fortunately it is easy to send an e-mail or chat with them on Facebook. It has also become much easier to keep up with the grandchildren's lives, [[15]] they and their parents often post pictures on Facebook. Grethe also talks to her daughter and her grandchildren on Skype several times a week. Then she can both hear and see them while they talk. She loves that, because she almost feels as if they are sitting together in the living room.\n\nBut Grethe does not only use the internet to keep in touch with family and friends. She [[16]] buys many different things on the internet. For example, she buys clothes, books and films. It is not [[17]], because the shops simply send everything she buys directly to her home.\n\nEven though Grethe no longer works, she has a [[18]] everyday life. For example, she does gymnastics, visits her friends and goes to the cinema, so she does not always have [[19]] to watch television. That is why Grethe is happy that you can watch many TV programmes on the internet. She [[20]] that often, you see.",
  "questions": [
   {}
  ]
 },
