 "p13-3": {
  "title": "Task 3 – Polite thief",
  "instruction": "Read the text. Choose the words (13-20) that are missing. There are five words you will not need. See the example (0).",
  "text": "A thief let himself into a summer house in West Jutland on a warm summer Saturday. Nobody was at home, because the family who lived in the house had gone down to the beach to swim in the [[0]] weather.\n\nIt was rather [[13]] for the thief to get in. The key was lying under a small, flat stone right next to the front door, so the thief found it almost immediately.\n\nWhen the family came home from the trip to the beach, they could [[14]] that they had had a guest. An expensive camera and a wallet with a little money and a Dankort were gone. They immediately called their bank and blocked the Dankort so that the thief could not [[15]] it. Some food from the fridge and a beer were [[16]] missing. The thief had obviously eaten lunch. But he had not made a mess in the kitchen, and he had done the washing-up after himself. On the dining table there was a piece of paper [[17]] which it said \"Thanks for the food!\"\n\nThe family thought it was a bit funny that it was a polite thief who had paid them a visit. But they were sad that he had [[18]] the camera with all their holiday photos. But a couple of days later a letter came with a CD and a small note. On the CD were their holiday photos. On the note it just said \"Thanks for the loan!\" They were [[19]] to get the photos back. And the little letter made them smile, [[20]] it was such a polite thief.",
  "questions": [
   {}
  ]
 },
 "p13-4": {
  "title": "Task 4 – Young mother",
  "instruction": "Read the text. One sentence is missing from each paragraph. Find the sentence (A-H) that fits in each paragraph (21-25). There are two sentences you will not need. See the example (0).",
  "text": "Sara Jensen lives a life that is very different from her friends'. She became a mother when she was only 17 years old.\n\n**0.** Today Sara is 19, and she lives with her son Noah in a flat in Sønderborg. Sara is not together with Noah's father, but he lives nearby, and Noah stays with him every other weekend. Sara's parents don't live far away either. [[0]]. It is nice for her to know that she can always call them and ask them to drop by if she needs to.\n\n**21.** A typical day for Sara starts early in the morning. The alarm clock rings at 6.15, and then there is an hour until she and Noah have to be out the door. Sara has a shower and gets breakfast ready before she wakes Noah. He has to get dressed and have breakfast, but he always much prefers to play. [[21]]. Then Sara gets a little stressed. But they always manage everything anyway, so Sara can drop Noah off at the nursery at 7.30.\n\n**22.** When Sara has dropped Noah off, she goes to school. She started the training to become a social and health care helper a couple of months ago. She likes going to school, and she is very focused while she is there. [[22]]. Of course she checks her phone during the breaks, because the nursery must be able to call her if he gets ill. But otherwise the most important thing for her is to learn something when she is at school.\n\n**23.** Sara's classmates often go to a café after school. But they don't ask her if she wants to come along, because they know she will say no. Sara would of course like to be with her friends from school, but she has to manage to tidy up and do the laundry before she picks up Noah. Because when Noah comes home from the nursery, she has to keep an eye on what he is doing all the time, and then she can't do very much else. [[23]]. Fortunately her classmates understand that.\n\n**24.** When Sara and Noah have had dinner, they watch children's TV, read stories and sing together. Sara also often gives Noah a bath before he goes to bed. But it is always important for Sara that he falls asleep quickly. She has homework to do, and if Noah is awake, she can't concentrate. And then she has to study at night when he finally sleeps, and that is really hard. [[24]]. So most of the time she gets her night's sleep.\n\n**25.** Many people ask Sara if she regrets having a child so early. But she doesn't. Of course she can feel that her everyday life is busy, and she is often tired. [[25]]. Because even though looking after Noah is a lot of work, the joy of having him is much greater. He is a lovely little boy who often gives his mother a big hug, and that always gives her new energy.",
  "questions": [
   {}
  ]
 },
 "p13-5": {
  "title": "Task 5 – Interview with Tine",
  "instruction": "Read the interview. Find the paragraph (A-H) that matches each of the five questions (26-30). There are two paragraphs you will not need. See the example (0).",
  "sections": [
   {
    "heading": "Interview with Tine – hairdresser in Odense",
    "cards": [
     {
      "title": "A",
      "sub": "Example",
      "body": "Well, what can I say? I like using my hands, and I like working with people and making them happy. And people just get so happy when their hair looks good. So it was probably those three things together that made me choose exactly this trade."
     },
     {
      "title": "B",
      "body": "That sometimes you can't sleep because you're thinking about money. I mean, do you have enough customers, and are you earning enough? You have a lot of expenses, after all. You have to pay rent. You owe the bank money. You have to buy new things. All of that can make you nervous."
     },
     {
      "title": "C",
      "body": "I don't really know. Then I would have to earn a lot of money. And I also want to have time for the people at home. Suddenly the children are grown up. Then I think I would probably be sorry that I had spent all my time on the job. But maybe later, when the children are older."
     },
     {
      "title": "D",
      "body": "It's hard to say, because there is so much. But maybe that by now I have quite a lot of regular customers. They almost become a kind of friends, because as a hairdresser you talk a lot with the customers. You talk about what you're doing and what you think and feel about all sorts of things. It's both exciting and lovely."
     },
     {
      "title": "E",
      "body": "Both yes and no. I have long working days, so I'm away a lot. Of course that's not so popular. But I'm almost never grumpy, because my job makes me happy, and that gives me energy to be active at home too. For example, I'm almost always ready to play a game with the children or bake a delicious cake. So now I actually think it's okay that I'm away quite a lot."
     },
     {
      "title": "F",
      "body": "Yes, well, you have to be good at telling people what to do. And you have to understand that people are different, and that this is actually good. And then you have to show them that you are a happy and friendly person. That simply means there aren't so many problems."
     },
     {
      "title": "G",
      "body": "It's hard, but it's also fun. It's hard that you always have to think about money, and you do. Because there are a great many hairdressers, so you have to make sure you hold on to your customers. But it's fun because you are building something up yourself."
     },
     {
      "title": "H",
      "body": "My salon is right in the middle of town, so many different kinds of people come here. Both very young people and pensioners come here. Children come here too, even the very little ones. And then of course people my own age come too. I mean, people of around 30-40."
     }
    ]
   }
  ],
  "questions": [
   {
    "q": "Which paragraph answers the question?",
    "items": [
     "Why did you become a hairdresser?",
     "What is it like to have your own salon?",
     "What kind of customers do you have?",
     "Is there anything about your job you don't like?",
     "What do you like best about your job?",
     "Is your family happy that you are a hairdresser?"
    ]
   }
  ]
 },
