 "p12n-3": {
  "title": "Task 3 – Free bikes for students",
  "instruction": "Read the text. Eight words are missing from the text (13-20). Choose the words that are missing. There are five words you will not need. See the example (0).",
  "text": "Now Danish students can borrow a new bike for a year – completely free. The student only has to pay a deposit of 500 kroner. The bikes are called Freebikes, and it [[0]] nothing to borrow them, because they are paid for by different companies.\n\nA company may put its name on the bike that the company pays for. The company may also decide what [[13]] the bike should have, so e.g. a Netto bike can be black and yellow. When a student then [[14]] around on the bike, the company gets a little advertising.\n\nWhen a student [[15]] his or her bike after a year, it is sent to Africa. There it is given to a young African who lives far from his or her school. In many African countries there are only upper secondary schools in the [[16]] towns. And there is not always public transport. So a bike can be a big help if you live in a small village and you [[17]] want to go to upper secondary school. In Denmark it is at the moment [[18]] students in Odense, Århus and Copenhagen who can borrow a free bike. But if the bikes become a success, students in other Danish [[19]] will also get the offer over the next couple of years. You can [[20]] more about the free bikes on the website www.freebikes.dk. It is also here you can order a free bike.",
  "questions": [
   {}
  ]
 },
 "p12n-4": {
  "title": "Task 4 – A life as a blind person",
  "instruction": "Read the text. One sentence is missing from each paragraph. Find the sentence (A-H) that fits in each paragraph (21-25). There are two sentences you will not need. See the example (0).",
  "text": "Mads Rasmussen is 19 years old. Two months ago he moved to Århus to study, like so many other young people. But Mads has a disability: He cannot see!\n\n**0.** Mads was born with an eye disease, which means that he is almost completely blind. In fact he can only see light and dark. [[0]]. For example, he has just moved into a hall of residence in Århus and has started studying music. That has been his big dream since he was a child.\n\n**21.** In the hall of residence Mads shares a kitchen with 7 other young students. That means a lot to him. Because as a blind person it can be a bit difficult to get to know new people when you can't make eye contact. But when you have a shared kitchen and eat together several times a day, it is much easier. [[21]]. They are both interested in music, so they often go to concerts together or sit in one of the rooms and listen to CDs.\n\n**22.** Mads has a long, white cane, which he always has with him when he walks around town. With it he can, for example, feel the road and the pavement. The cane also means that other people can see that he is blind. He is glad about that, because then people can step aside. [[22]]. Some people would very much like to help Mads. For example, they take him by the arm even though he hasn't asked them to. He doesn't like that, and then he says politely, but firmly, that he doesn't need help.\n\n**23.** In everyday life Mads does his own shopping. He asks the staff and the other customers in the supermarket for help, and then it goes fine. But it is difficult for him to buy clothes. [[23]]. She goes with him to shops and makes sure that the clothes he buys match in colour. And she always gives her opinion if he tries on clothes that don't suit him. It has been like that since the two siblings were children.\n\n**24.** There are various technical aids that make everyday life easier for Mads. For example, his mobile phone can read his text messages aloud to him. And his computer has a speech program, so he can listen to the texts he gets on his course. [[24]]. Because it means that he can manage his studies without help from others.\n\n**25.** So Mads lives an independent life with studies, free time and friends, even though he is blind. Of course he has to plan his day well. There are also many things that take longer for him because he cannot see. [[25]]. And maybe that is why Mads doesn't think it is a problem. For him the most important thing is that he can manage on his own.",
  "questions": [
   {}
  ]
 },
 "p12n-5": {
  "title": "Task 5 – Interview with Jytte",
  "instruction": "Read the interview. Find the paragraph (A-H) that matches each of the five questions (26-30). There are two paragraphs you will not need. See the example (0).",
  "sections": [
   {
    "heading": "Interview with Jytte – bakery shop assistant at Kvickly",
    "cards": [
     {
      "title": "A",
      "sub": "Example",
      "body": "I'm crazy about dogs, and we have three at home. They need a lot of exercise, so they have to have some long walks every day. For me it is the best way to relax after a long working day. At the weekend I often drive to the beach and walk them there."
     },
     {
      "title": "B",
      "body": "Yes, I do. And I actually have many. One of them has shopped with me since the bakery opened. She is an elderly lady who comes every Friday and buys cakes to have with coffee. Then we almost always have a little chat. We both like that."
     },
     {
      "title": "C",
      "body": "Actually not as bad as you might think. I mean, it rarely has anything to do with me if people are in a bad mood. Maybe they are stressed or tired. Then I'm just extra professional and polite towards them. And then I'm glad that most people are friendly and nice."
     },
     {
      "title": "D",
      "body": "No, because the shop didn't have a bakery at all when I started. For the first couple of years I sat at the till. And then I was in fruit and vegetables for a while. But I have been a shop assistant in the bakery since it opened almost 19 years ago."
     },
     {
      "title": "E",
      "body": "I actually don't think I can think of anything bad. Oh yes, now I know. The cakes! I love cakes, and that's why I eat far too many. I'm sorry about that, because I'm a bit too fat. But it's difficult when you're holding them in your hands all day."
     },
     {
      "title": "F",
      "body": "No, actually never. I have some young colleagues who have part-time jobs in the shop. They have to take care of their studies, so they don't mind working late. And then the rest of us can leave early. I'm glad about that. I'm a morning person, you see."
     },
     {
      "title": "G",
      "body": "That's a difficult question, because there are several things. But if I can only give one answer, it will be: my colleagues! They are absolutely fantastic. One of them has been here just as long as me, and we are also friends privately. But I also get on well with the young people who work here."
     },
     {
      "title": "H",
      "body": "So many people ask that! Of course I have tasted all the different kinds we have in the shop. And more than once, too. I think that's part of the job. But like so many others, I have to watch my weight. So I only take a little something sweet home to have with coffee a couple of times a week."
     }
    ]
   }
  ],
  "questions": [
   {
    "q": "Which paragraph answers the question?",
    "items": [
     "What do you do when you are off work?",
     "What do you like best about your job?",
     "Have you always worked in the same department?",
     "Do you often eat cakes?",
     "How do you feel about grumpy customers?",
     "Do you often have evening shifts?"
    ]
   }
  ]
 },
