  "instruction": "Read the text. A sentence is missing in each paragraph. Find the sentence (A-H) that fits in each paragraph (21-25). There are two sentences you will not use. See the example (0).",
  "text": "Samira Haddad is 34 years old and came to Denmark from Lebanon ten years ago. Today she has her own hair salon in Kolding.\n\n**0.** In Lebanon, Samira worked as a hairdresser for many years. When she came to Denmark, she could not speak Danish, and she got a job as a cleaner. [[0]]. She missed cutting hair and talking to the customers.\n\n**21.** Samira started at language school in the evenings, and after three years she passed Prøve i Dansk 2. [[21]]. There she learned both about Danish hair care and about how to run a business.\n\n**22.** After her training, she got a job in a large salon in the centre of Kolding. She liked her colleagues, but the pay was low and the working hours were long. [[22]]. She wanted to make her own decisions.\n\n**23.** However, it was not easy to start a business. Samira had to borrow money, and she had to find premises. [[23]]. In the end, a business adviser from the municipality helped her make a good business plan.\n\n**24.** In March last year, Samira finally opened her own salon. In the first months, not many customers came. [[24]]. She made a Facebook page and gave discounts to new customers.\n\n**25.** Today the salon is busy, and Samira has hired two employees. [[25]]. “I want to show other women that it can be done,” she says.",
